package migrations

import (
	"github.com/pocketbase/dbx"
	"github.com/pocketbase/pocketbase/daos"
	m "github.com/pocketbase/pocketbase/migrations"
	"github.com/pocketbase/pocketbase/models"
	"github.com/pocketbase/pocketbase/models/schema"
	"github.com/pocketbase/pocketbase/tools/types"
)

func init() {
	m.Register(func(db dbx.Builder) error {
		dao := daos.New(db)

		// 1. Create the configs collection
		collection := &models.Collection{
			Name:     "configs",
			Type:     models.CollectionTypeBase,
			ListRule: types.Pointer(""),
			ViewRule: types.Pointer(""),
			Schema: schema.NewSchema(
				&schema.SchemaField{
					Name:     "key",
					Type:     schema.FieldTypeText,
					Required: true,
				},
				&schema.SchemaField{
					Name:     "value",
					Type:     schema.FieldTypeText,
					Required: false,
				},
			),
		}

		if err := dao.SaveCollection(collection); err != nil {
			return err
		}

		// 2. Insert initial records
		record1 := models.NewRecord(collection)
		record1.Set("key", "site_name")
		record1.Set("value", "My Site")
		if err := dao.SaveRecord(record1); err != nil {
			return err
		}

		record2 := models.NewRecord(collection)
		record2.Set("key", "maintenance_mode")
		record2.Set("value", "false")
		if err := dao.SaveRecord(record2); err != nil {
			return err
		}

		return nil
	}, func(db dbx.Builder) error {
		dao := daos.New(db)

		collection, err := dao.FindCollectionByNameOrId("configs")
		if err != nil {
			return err
		}

		return dao.DeleteCollection(collection)
	})
}

package main

import (
	"log"

	"github.com/pocketbase/pocketbase"
	"github.com/pocketbase/pocketbase/plugins/migratecmd"
	_ "myproject/migrations"
)

func main() {
	app := pocketbase.New()

	migratecmd.MustRegister(app, app.RootCmd, migratecmd.Config{
		Automigrate: true,
	})

	if err := app.Start(); err != nil {
		log.Fatal(err)
	}
}

