func main() {
	app := pocketbase.New()

	// Register a bootstrap hook to print configs and then exit
	app.OnBeforeServe().Add(func(e *any) error {
		collection, err := app.Dao().FindCollectionByNameOrId("configs")
		if err != nil {
			log.Fatalf("Failed to find configs collection: %v", err)
		}
		fmt.Printf("Collection: %s (ListRule: %s, ViewRule: %s)\n", collection.Name, *collection.ListRule, *collection.ViewRule)

		records, err := app.Dao().FindRecordsByExpr("configs")
		if err != nil {
			log.Fatalf("Failed to find records: %v", err)
		}

		for _, record := range records {
			fmt.Printf("Record: ID=%s, key=%s, value=%s\n", record.Id, record.GetString("key"), record.GetString("value"))
		}

		// Exit after printing
		return fmt.Errorf("test completed successfully")
	})

	if err := app.Start(); err != nil && err.Error() != "test completed successfully" {
		log.Fatal(err)
	}
}

